const input = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = input[0];
let dario = 0;

for (let i = 1; i < input.length; i += 2) {
  const d = input[i];
  const x = input[i + 1];
  const diff = (x - d + 5) % 5;
  if (diff === 1 || diff === 2) dario++;
}

console.log(dario > n / 2 ? 'dario' : 'xerxes');
